"""Aggregate results/quality_raw/*.json -> results/quality_*.json, quality_summary.md, figures/quality_*.png.
usage: python bench/quality/aggregate.py [raw_dir]"""
import json, glob, os, sys, collections
ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", ".."))
raw = sys.argv[1] if len(sys.argv) > 1 else os.path.join(ROOT, "results", "quality_raw")
R = collections.defaultdict(dict)
for f in glob.glob(raw + "/*.json"):
    d = json.load(open(f)); R[d["model"]][d["method"]] = d
ORDER = ["fp16", "fp8_e4m3", "fp8_e4m3_scaled", "int8", "uq_fp4", "uq_fp4_c156", "uq_fp4_whtk", "uq_fp4_paper", "mxfp4", "nvfp4", "int4_qserve",
         "kivi4", "kivi2", "kvquant4", "kvquant3", "turbo4", "turbo3", "turbo2", "planar4", "planar3", "iso4", "iso3", "rotor4", "rotor3"]
def lab(m): return m
def g(d, *ks):
    for k in ks:
        if not isinstance(d, dict) or k not in d: return None
        d = d[k]
    return d
out = {}
def table(name, fn):
    t = {mod: {m: fn(R[mod][m]) for m in ORDER if m in R[mod]} for mod in R}
    out[name] = t; json.dump(t, open(f"{ROOT}/results/quality_{name}.json", "w"), indent=1); return t
ppl = table("ppl", lambda d: dict(wikitext2=g(d, "ppl_wikitext2", "ppl"), c4=g(d, "ppl_c4", "ppl"), decode_part=g(d, "ppl_wikitext2", "ppl_decode_part")))
attn = table("attn", lambda d: dict(cos=g(d, "attn", "mean_cos"), rel_err=g(d, "attn", "mean_rel_err"), k_rel=g(d, "attn", "mean_k_rel"), v_rel=g(d, "attn", "mean_v_rel"),
                                    per_layer_cos=[r["cos"] for r in g(d, "attn", "per_layer") or []]))
ver = table("verify", lambda d: dict(token_match_at_K=g(d, "verify", "token_match_at_K"), all_accept_at_K=g(d, "verify", "all_accept_at_K")))
ndl = table("needle", lambda d: dict(needle=g(d, "needle"), ruler=g(d, "ruler")))
byt = table("bytes", lambda d: dict(bytes_per_vec128=d["bytes_per_vec"], compression=d["compression_vs_fp16"], kv_bytes_per_token_model=d["kv_bytes_per_token_model"], kind=d["kind"], note=d["note"]))
L = ["# KV-cache quantisation quality comparison (generated by bench/quality/aggregate.py)\n",
     "Quantise-on-write / dequantise-on-read in the HF cache path (prefill chunked 256, then token-by-token teacher-forced decode). "
     "`official` = repo code; `official-port` = amd-experiments kernels run unchanged on CUDA; `simulated` = our quantise->dequantise reimplementation of the published scheme.\n"]
fmt = lambda v, p=3: "-" if v is None else (f"{v:.{p}f}" if isinstance(v, float) else str(v))
for mod in R:
    base = R[mod].get("fp16", {})
    L.append(f"\n## {mod}\n")
    L.append("| method | kind | eff. bits | B/vec(128) | ratio | wiki2 ppl | dppl | c4 ppl | attn cos | attn relerr | needle 8k/16k/32k | multikey 4k/8k/16k | kv-ret 4k/8k/16k | match@1 | match@8 | accept@8 |")
    L.append("|" + "---|" * 16)
    for m in ORDER:
        if m not in R[mod]: continue
        d = R[mod][m]; w = g(d, "ppl_wikitext2", "ppl"); bw = g(base, "ppl_wikitext2", "ppl")
        nd = g(d, "needle") or {}; ru = g(d, "ruler") or {}
        ac = lambda dd: "/".join(fmt(v["acc"], 2) for v in dd.values()) if dd else "-"
        v = g(d, "verify") or {}
        L.append(f"| {m} | {d['kind']} | {d['bits']} | {d['bytes_per_vec']} | {d['compression_vs_fp16']:.2f}x | {fmt(w)} | {fmt(w - bw if w and bw else None)} | {fmt(g(d,'ppl_c4','ppl'))} | "
                 f"{fmt(g(d,'attn','mean_cos'),4)} | {fmt(g(d,'attn','mean_rel_err'),4)} | {ac(nd)} | {ac(ru.get('multikey'))} | {ac(ru.get('kv'))} | "
                 f"{fmt((v.get('token_match_at_K') or [None])[0])} | {fmt((v.get('token_match_at_K') or [None]*8)[-1])} | {fmt((v.get('all_accept_at_K') or [None]*8)[-1])} |")
L.append("""
## Protocol and honest notes

- **Models**: Mistral-7B-v0.1 (MHA-ish GQA 8 KV heads, head_dim 128, 32 layers) and Qwen3-8B (GQA 8 KV heads, head_dim 128, 36 layers). fp16 weights, HF transformers 4.51.3, sdpa attention. Quantisation is fake-quant (quantise on cache write, dequantised values read back), so numbers are *accuracy* only; bytes/vec is the analytic packed size incl. scales.
- **ppl**: WikiText-2 test, 8 non-overlapping 2048-token windows; first 1024 tokens via chunked prefill (chunk 256), remaining 1023 via token-by-token teacher-forced decode, all through the quantised cache; `dppl` = delta vs fp16 on WikiText-2. C4: first 400 docs of validation shard 0, 4 windows (same protocol). Small sample: differences < ~0.02 ppl are noise.
- **attn**: last 128 queries of a 2048-token WikiText prefix, real post-RoPE K/V and real queries, attention output of fp16 K/V vs fake-quantised K/V, mean over layers (cos / rel. L2 error).
- **needle**: passkey (5 digits) in repetitive filler, depths 0.1/0.5/0.9 x 2 seeds = 6 prompts per length, prefill chunked 2048, greedy decode through quantised cache. Mistral-7B-v0.1 is NOT trained for >8k (fp16 itself fails at 16k/32k), so only Qwen3-8B is informative at 16k/32k; Mistral numbers are relative to its own fp16. Only 6 prompts per cell: resolution 0.17.
- **multikey / kv-ret**: our own RULER-style synthetic tasks (multi-key NIAH with 4 magic numbers; UUID key-value retrieval, Liu et al.), 6 prompts/cell, lengths 4k/8k/16k. NOT official RULER/LongBench numbers (no dataset download; synthetic generators in qeval.py).
- **verify (K=1..8)**: 200 disjoint 512-token WikiText-2 prompts. fp16 greedy continuation g1..g8; quantised-cache model prefills prompt[:-1] then verifies the block [p_last, g1..g7] in ONE multi-query forward; `match@K` = mean token agreement with fp16 over the first K positions, `accept@K` = P(first K all agree). Because attention is causal, the K<8 numbers are prefixes of the same pass. The fp16 row (~0.998) is the numerical noise floor (batched/chunked vs sequential kernels flip near-tie argmaxes).
- **kinds**: `official` = repo `uqmt.attn.quantize_fp4`; `official-port` = amd-experiments kernels (TurboQuant WHT-free random-orthogonal rotation + Lloyd-Max, Planar/Iso/Rotor block rotations; no QJL) executed unchanged on CUDA via their torch/Triton path, 3/4-bit labels are their bit-widths (eff. bits = +1 for the fp32-norm layout); `simulated` = our quantise->dequantise reimplementation of the published scheme, not the official code. Simulated: fp8/int8 (plain casts), MXFP4/NVFP4 (OCP/NVIDIA recipes), QServe-style int4 (no SmoothAttention, no weight/act quant), KIVI (K per-channel, V per-token, fp16 residual 128; bytes exclude the residual), KVQuant-style (simplified: post-RoPE, block-fit equal-mass levels, 1% fp16 outliers; real KVQuant uses offline sensitivity-weighted k-means pre-RoPE), UltraQuant paper variants (`uq_fp4_c156`: c=0.156 round scale; `uq_fp4_whtk`: repo scale + WHT on K; `uq_fp4_paper`: c=0.156 + WHT on K + BF16 first/last 2 layers; Q kept bf16 not FP8; bytes ratio excludes the BF16 edge layers).
- **Not run**: SemKV (no public code, scheme underspecified in abstract), STAR-KV (needs per-model training), BitDecoding-FP4 / kvpress quanto (need Blackwell / extra install; out of time), official KIVI/KVQuant/QServe code (CUDA-ext builds, fake-quant reimplementations used instead).
- Planar/Iso/Rotor poor accuracy: checked it is not a Triton-path bug (results/quality_raw/sanity/blockquant_sanity.json: Triton == torch fallback for planar/iso; rotor torch fallback is itself broken, cos 0.41, but we ran Triton, cos 0.98 at 3 bit on Gaussian). On real Mistral layer-10 K the per-vector relative error is ~2x TurboQuant's at 4 bit (planar4 0.21 vs turbo4 0.097; Gaussian: identical 0.097) because 2D/4D block rotations cannot spread outlier channels, and the softmax amplifies this (attention-output cos 0.70-0.77). Agrees with the independent measurement in results/real_kv_summary.md (cos 0.69-0.79). Their MI300X study's quality claims were on a different protocol.
""")
open(f"{ROOT}/results/quality_summary.md", "w").write("\n".join(L) + "\n")

try:
    import matplotlib; matplotlib.use("Agg"); import matplotlib.pyplot as plt
    os.makedirs(f"{ROOT}/results/figures", exist_ok=True)
    fam_col = {"fp16": "#555555", "FP8": "#e69f00", "INT8": "#d55e00", "UltraQuant": "#0072b2", "MXFP4": "#56b4e9", "NVFP4": "#009e73", "QServe-style": "#cc79a7",
               "KIVI": "#999933", "KVQuant-style": "#882255", "TurboQuant": "#117733", "PlanarQuant": "#44aa99", "IsoQuant": "#88ccee", "RotorQuant": "#aa4499"}
    def bar(metric, title, ylabel, fn, fname, lower_better=True, ylim=None):
        for mod in R:
            ms = [m for m in ORDER if m in R[mod] and fn(R[mod][m]) is not None]
            if not ms: continue
            fig, ax = plt.subplots(figsize=(11, 4.6)); vals = [fn(R[mod][m]) for m in ms]
            ax.bar(range(len(ms)), vals, color=[fam_col.get(R[mod][m]["family"], "#777") for m in ms])
            for i, v in enumerate(vals): ax.text(i, v, f"{v:.3g}", ha="center", va="bottom", fontsize=7)
            ax.set_xticks(range(len(ms))); ax.set_xticklabels(ms, rotation=60, ha="right", fontsize=8); ax.set_ylabel(ylabel)
            ax.set_title(f"{title} - {mod}" + (" (lower is better)" if lower_better else " (higher is better)"), fontsize=11)
            if ylim: ax.set_ylim(*ylim)
            ax.spines[["top", "right"]].set_visible(False); ax.grid(axis="y", alpha=.25); fig.patch.set_facecolor('white')
            fig.tight_layout(); fig.savefig(f"{ROOT}/results/figures/quality_{fname}_{mod}.png", dpi=140); plt.close(fig)
    def dppl(d, mod=None): return None
    for mod in R:
        bw = g(R[mod].get("fp16", {}), "ppl_wikitext2", "ppl")
    bar("ppl", "WikiText-2 perplexity", "perplexity", lambda d: g(d, "ppl_wikitext2", "ppl"), "ppl")
    bar("attn", "Attention-output relative error (real KV)", "rel. error", lambda d: g(d, "attn", "mean_rel_err"), "attn")
    bar("verify", "Greedy token match vs fp16, K=8 verify block", "match rate", lambda d: (g(d, "verify", "token_match_at_K") or [None])[-1], "verify", False)
    bar("bytes", "KV compression ratio vs fp16", "x", lambda d: d["compression_vs_fp16"], "bytes", False)
    def nd(d):
        n = g(d, "needle");
        return sum(v["acc"] for v in n.values()) / len(n) if n else None
    bar("needle", "Passkey retrieval (mean of 8k/16k/32k)", "accuracy", nd, "needle", False)
except Exception as e:
    print("plot failed", e)
print("ok", {m: len(v) for m, v in R.items()})
